package com.portfolio.fraud.security; import com.portfolio.fraud.entity.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.util.*; @Service public class JwtService { private final com.portfolio.fraud.service.SessionService sessions; private final byte[] secret; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String s,@Value("${app.jwt.expiration-ms}") long e,com.portfolio.fraud.service.SessionService sessions){this.sessions=sessions;secret=s.getBytes(StandardCharsets.UTF_8);expiration=e;} public String create(User u){return Jwts.builder().subject(u.getEmail()).id(sessions.create(u)).claim("role",u.getRole().name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(Keys.hmacShaKeyFor(secret)).compact();} public Claims claims(String token){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret)).build().parseSignedClaims(token).getPayload();} }
